WITH enriched AS (SELECT id, session_id, AVG(duration_sec) OVER w_running AS last7_avg_duration_sec, MIN(duration_sec) OVER w_running AS last7_min_duration_sec, COUNT(duration_sec) OVER w_running AS last7_count_duration_sec, ROW_NUMBER() OVER (ORDER BY event_time, id) AS row_seq FROM web_events WHERE event_type IN ('purchase', 'search', 'page_view') WINDOW w_running AS (PARTITION BY session_id ORDER BY duration_sec, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW)) SELECT id, last7_avg_duration_sec, last7_min_duration_sec, last7_count_duration_sec, row_seq FROM enriched
